import{z as p,x as d,o,c as B,q as s,j as l,D as t,d as n,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"复制式 GC","description":"","frontmatter":{"title":"复制式 GC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/copying-gc.md","filePath":"cs/copying-gc.md","lastUpdated":1791413859000}'),C={name:"cs/copying-gc.md"};function m(A,a,c,h,g,u){const r=d("Mermaid");return o(),B("div",null,[a[2]||(a[2]=s('<h1 id="复制式-gc" tabindex="-1">复制式 GC <a class="header-anchor" href="#复制式-gc" aria-label="Permalink to &quot;复制式 GC&quot;">​</a></h1><div class="epigraph"><p>堆分成 from 与 to。从根出发把活对象搬到 to，留下转发指针。结束后交换半区。碎片自然消失，代价是堆只用一半。</p><footer>—— 据 Cheney, A Nonrecursive List Compacting Algorithm, 1970；Jones, Hosking and Moss, The Garbage Collection Handbook；主干[标记清除与分代](/cs/gc-mark-gen) 整理</footer></div><p>上一课<a href="/cs/jit-escape-analysis">JIT 逃逸</a> 减少分配。仍逃逸的对象进堆。主干 GC 课有标记-清扫直觉。缺口是<strong>复制式</strong>：Cheney 扫描、转发。内存管理课序从这里开始。引用计数下一课对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标记-清扫有碎片，分配要空闲表。复制：bump 指针在 to 区线性分配活对象。缺口是<strong>搬运与指针更新</strong>，不是逃逸分类。</p><p>Cheney：用 to 区当队列，广度扫描，无需递归栈。</p><h3 id="半区不是「浪费一半就慢一倍」" tabindex="-1">半区不是「浪费一半就慢一倍」 <a class="header-anchor" href="#半区不是「浪费一半就慢一倍」" aria-label="Permalink to &quot;半区不是「浪费一半就慢一倍」&quot;">​</a></h3><p>吞吐常更好（只碰活对象）。空间换时间。分代后幼代用复制，老年代另策略——后课。</p><p><span class="marginnote">Cheney 1970。Appel 的简单分代。Jones 手册。主干 runtime-gc、gc-mark-gen。</span></p><p><span class="marginnote">初学者容易以为堆砍一半吞吐必然减半；实际上复制式只碰活对象，若一次回收后活对象只占两成，GC 的工作量跟全堆大小无关，总账常比标记-清扫还划算——前提恰恰是「大多数对象朝生暮死」，这也是分代假说愿意把幼代交给复制的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>翻转半区。扫描根，搬迁，写转发。扫描 to 区新对象的指针，直到队列空。更新栈与寄存器。JIT：安全点上的栈图给出根。</p>',12)),(o(),l(E,null,{default:t(()=>[i(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%22%5D%20--%3E%20COPY%5B%22%E6%90%AC%E5%88%B0%20to%22%5D%0A%20%20COPY%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%E6%8C%87%E9%92%88%22%5D%0A%20%20FWD%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%20to%20%E5%8C%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与精确 vs 保守：保守不能随便搬（不清楚是不是指针）。复制式通常要精确根。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"bump 分配可以想象成发号器：要多少字节就把指针往前拨多少，永远不用找空隙。这正是复制式消灭碎片的收益——to 区里活对象一个挨一个，空闲空间永远是完整的一整块，而不是清扫后那堆东一块西一块的洞。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"大对象可进独立区不复制。多线程：每个线程 TLAB，后课。不要在非安全点搬对象，JIT 寄存器里的指针会丢。",-1)),a[7]||(a[7]=e("p",null,"与 deopt 物化：新对象当分配，可直接在 to 或 TLAB。",-1)),(o(),l(E,null,{default:t(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E6%89%AB%E6%8F%8F%E4%B8%AD%E9%81%87%E5%88%B0%E6%8C%87%E5%90%91%E8%80%81%E5%9C%B0%E5%9D%80%E7%9A%84%E5%BC%95%E7%94%A8%22%5D%20--%3E%20Q%5B%22%E8%80%81%E5%9C%B0%E5%9D%80%E5%B7%B2%E6%9C%89%E8%BD%AC%E5%8F%91%E6%8C%87%E9%92%88%3F%22%5D%0A%20%20Q%20--%20%22%E6%B2%A1%E6%9C%89%20%E9%A6%96%E6%AC%A1%E9%81%87%E5%88%B0%22%20--%3E%20MOVE%5B%22%E6%90%AC%E8%BF%9B%20to%20%E5%8C%BA%20%E7%95%99%E4%B8%8B%E8%BD%AC%E5%8F%91%E6%8C%87%E9%92%88%22%5D%0A%20%20Q%20--%20%22%E6%9C%89%20%E5%B7%B2%E7%BB%8F%E6%90%AC%E8%BF%87%22%20--%3E%20USE%5B%22%E7%9B%B4%E6%8E%A5%E6%94%B9%E5%86%99%E6%88%90%E6%96%B0%E5%9C%B0%E5%9D%80%22%5D%0A%20%20MOVE%20--%3E%20USE%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">转发指针就是搬家后在老门牌上贴的「已迁至新址」字条：老位置只留一个指针指向新家。GC 第二次遇到同一对象的旧引用时，看一眼字条就能改写，不必搬第二次——否则同一对象会被复制成多份、堆里出现分身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写引用计数。后课默认：幼代常用复制。下一课引用计数 GC。</p><p>也不把复制当 memcpy 课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复制式：搬活对象，消碎片，堆用半区。</li><li>Cheney 用 to 区当工作队列。</li><li>需要精确根与安全点。</li><li>出处：Cheney, 1970；Jones et al. 手册。</li></ul>',6))])}const T=p(C,[["render",m]]);export{D as __pageData,T as default};
